-- Infinity Horlogerie — catalog v2: replace the fictional house catalog with
-- the real db catalog (9 Tissot / Tag Heuer models, photos in Storage).

delete from public.reviews;
delete from public.product_variants;
delete from public.products;
delete from public.collections;

insert into public.collections (id, slug, name, eyebrow, description, hero_image) values
  ('20000000-0000-4000-8000-000000000001'::uuid, 'tissot', 'Tissot', 'Swiss heritage since 1853',
   'Swiss precision, honest prices, worn well. From the Carson to the PRX, the Tissot line is the everyday side of fine watchmaking.',
   'https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-gentleman-quartz.png'),
  ('20000000-0000-4000-8000-000000000002'::uuid, 'tag-heuer', 'Tag Heuer', 'Avant-garde timing',
   'The Aquaracer line — engineered for the deep, styled for the city. A diving tool that never stopped dressing up.',
   'https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tag-heuer-aquaracer-professional.png');

insert into public.products (
  id, slug, name, subtitle, collection_id, price_cents, currency, tagline, description,
  long_description, images, specs, bestseller, new_arrival, stock
) values
  ('10000000-0000-4000-8000-000000000001'::uuid, 'tissot-carson-premium-ladies', 'Tissot Carson Premium Ladies',
   'T122.210.11.033.00 · 30mm',
   (select id from public.collections where slug = 'tissot'),
   134300, 'USD', 'A women''s timeless choice.',
   'A classic 30mm ladies'' watch in polished stainless steel with a silver dial — quiet, elegant, and built to be worn daily.',
   'The Carson Premium Ladies pairs a compact 30mm stainless steel case with a clean silver dial and a matching steel bracelet. At 70 grams it sits weightlessly on the wrist, powered by a reliable Swiss quartz movement that keeps it accurate for years with no more than a battery change.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-carson-premium-ladies.png"]'::jsonb,
   '[{"label":"Model","value":"T122.210.11.033.00"},{"label":"Movement","value":"Quartz"},{"label":"Diameter","value":"30mm"},{"label":"Dial","value":"Silver"},{"label":"Weight","value":"70g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, false, 8),
  ('10000000-0000-4000-8000-000000000002'::uuid, 'tissot-seastar-chronograph-black', 'Tissot Seastar Chronograph',
   'T120.417.11.051.01 · 45.5mm',
   (select id from public.collections where slug = 'tissot'),
   172900, 'USD', 'Sporty performance along timeless luxury.',
   'A black-dialed diving chronograph from the Seastar line — bold, water-ready, and finished like a much more expensive watch.',
   'The Seastar Chronograph brings 300m water resistance, a unidirectional bezel, and a quartz chronograph movement into a rugged 45.5mm steel case. The black dial reads clearly in deep water and bright sunlight alike, and the steel bracelet keeps the whole 180-gram package securely planted.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-seastar-chronograph-black.png"]'::jsonb,
   '[{"label":"Model","value":"T120.417.11.051.01"},{"label":"Movement","value":"Quartz Chronograph"},{"label":"Diameter","value":"45.5mm"},{"label":"Dial","value":"Black"},{"label":"Weight","value":"180g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   true, false, 8),
  ('10000000-0000-4000-8000-000000000003'::uuid, 'tag-heuer-aquaracer-professional', 'Tag Heuer Aquaracer Professional 300',
   'WBP201B.BA0632 · 43mm',
   (select id from public.collections where slug = 'tag-heuer'),
   554200, 'USD', 'Built for 300 metres. Worn everywhere.',
   'A 43mm professional diver with a blue sunray dial, ceramic bezel, and the Calibre 5 automatic — the definitive Aquaracer.',
   'The Aquaracer Professional 300 Date is Tag Heuer''s modern dive watch. A scratch-resistant blue ceramic unidirectional bezel frames a sunray-brushed dial with horizontal deck-style lines, driven by the self-winding Calibre 5 with a ~38-hour power reserve. The fine-brushed steel bracelet closes with a double-safety push-button folding clasp.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tag-heuer-aquaracer-professional.png"]'::jsonb,
   '[{"label":"Model","value":"WBP201B.BA0632"},{"label":"Movement","value":"Calibre 5 Automatic Swiss"},{"label":"Diameter","value":"43mm"},{"label":"Dial","value":"Blue sunray"},{"label":"Weight","value":"~175g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel · blue ceramic bezel"}]'::jsonb,
   true, true, 8),
  ('10000000-0000-4000-8000-000000000004'::uuid, 'tissot-pr100-chronograph', 'Tissot PR100 Chronograph',
   'T101.417.22.031.00 · 41mm',
   (select id from public.collections where slug = 'tissot'),
   144500, 'USD', 'Classic silver & refined gold.',
   'A two-tone chronograph — silver dial, gold-tone accents, and a 41mm steel case that bridges sport and dress.',
   'The PR100 Chronograph offers everything a first chronograph should: three readable counters, a date window, and a two-tone silver-and-gold finish that works from the boardroom to the weekend. The quartz chronograph movement keeps it fuss-free and accurate.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-pr100-chronograph.png"]'::jsonb,
   '[{"label":"Model","value":"T101.417.22.031.00"},{"label":"Movement","value":"Quartz Chronograph"},{"label":"Diameter","value":"41mm"},{"label":"Dial","value":"Silver"},{"label":"Weight","value":"145g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, false, 8),
  ('10000000-0000-4000-8000-000000000005'::uuid, 'tissot-gentleman-quartz', 'Tissot Gentleman Quartz',
   'T127.410.11.041.00 · 40mm',
   (select id from public.collections where slug = 'tissot'),
   132400, 'USD', 'Elegant, timeless & quiet luxury.',
   'A 40mm blue-dialed daily in polished steel — the quiet-luxury GADA watch, accurate to the second.',
   'The Gentleman is the modern definition of quiet luxury: a 40mm polished case, a deep blue dial, and a Swiss quartz movement accurate to ±10 seconds a year. At 142 grams it has a reassuring presence without ever shouting, and its fine-brushed bracelet sits flat and comfortable.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-gentleman-quartz.png"]'::jsonb,
   '[{"label":"Model","value":"T127.410.11.041.00"},{"label":"Movement","value":"Quartz"},{"label":"Diameter","value":"40mm"},{"label":"Dial","value":"Blue"},{"label":"Weight","value":"142g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, true, 8),
  ('10000000-0000-4000-8000-000000000006'::uuid, 'tissot-traditional-chronograph', 'Tissot Traditional Chronograph',
   'T063.617.36.037.00 · 42mm',
   (select id from public.collections where slug = 'tissot'),
   140400, 'USD', 'Light weight, simple & elegant.',
   'A featherweight 42mm chronograph on a leather belt — simple, elegant, and almost unnoticeable on the wrist.',
   'At just 67 grams, the Traditional Chronograph is one of the lightest chronographs you''ll wear. Its white dial and slim steel case keep things dressy, while the genuine leather strap adds warmth. A quartz movement keeps the three counters and date honest.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-traditional-chronograph.png"]'::jsonb,
   '[{"label":"Model","value":"T063.617.36.037.00"},{"label":"Movement","value":"Quartz"},{"label":"Diameter","value":"42mm"},{"label":"Dial","value":"White"},{"label":"Weight","value":"67g"},{"label":"Bracelet","value":"Leather"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, false, 8),
  ('10000000-0000-4000-8000-000000000007'::uuid, 'tissot-seastar-chronograph-blue', 'Tissot Seastar Chronograph',
   'T120.417.11.041.01 · 45.5mm',
   (select id from public.collections where slug = 'tissot'),
   172900, 'USD', 'Sporty performance along timeless luxury.',
   'The same 300m-ready Seastar chronograph, now in a blue-gradient dial that shifts from deep navy to bright blue.',
   'A gradient blue dial elevates the Seastar Chronograph from tool to statement. The 45.5mm steel case, ceramic bezel, and quartz chronograph remain, but the dial — dark at the edges, glowing at the centre — catches the light with every turn of the wrist.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-seastar-chronograph-blue.png"]'::jsonb,
   '[{"label":"Model","value":"T120.417.11.041.01"},{"label":"Movement","value":"Quartz Chronograph"},{"label":"Diameter","value":"45.5mm"},{"label":"Dial","value":"Blue gradient"},{"label":"Weight","value":"180g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, false, 8),
  ('10000000-0000-4000-8000-000000000008'::uuid, 'tissot-carson-chronograph', 'Tissot Carson Chronograph',
   'T122.417.11.011.00 · 41mm',
   (select id from public.collections where slug = 'tissot'),
   166100, 'USD', 'Classic, refined & timeless.',
   'A white-dialed three-counter chronograph in polished steel — the Carson name, now with a stopwatch.',
   'The Carson Chronograph takes the house''s best-selling dress-watch DNA and adds three legible counters and a date. The white dial is framed by a polished 41mm steel case, and the whole piece walks the line between tool and formal without choosing.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-carson-chronograph.png"]'::jsonb,
   '[{"label":"Model","value":"T122.417.11.011.00"},{"label":"Movement","value":"Quartz"},{"label":"Diameter","value":"41mm"},{"label":"Dial","value":"White"},{"label":"Weight","value":"113g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   true, false, 8),
  ('10000000-0000-4000-8000-000000000009'::uuid, 'tissot-prx-quartz', 'Tissot PRX Quartz',
   'T137.410.11.041.00 · 40mm',
   (select id from public.collections where slug = 'tissot'),
   136700, 'USD', 'The perfect blend of sport and sophistication.',
   'The integrated-bracelet icon — a dark-blue 40mm PRX with the instantly recognisable 1970s case.',
   'The PRX''s integrated steel case and bracelet are pure 1970s, and still the most recognisable silhouette Tissot makes. The dark-blue waffle dial is crisp under any light, powered by a Swiss quartz movement accurate to ±10 seconds a year. One watch, every occasion.',
   '["https://hldgqsutdgozdnhexpys.supabase.co/storage/v1/object/public/products/tissot-gentleman-quartz.png"]'::jsonb,
   '[{"label":"Model","value":"T137.410.11.041.00"},{"label":"Movement","value":"Swiss Quartz"},{"label":"Diameter","value":"40mm"},{"label":"Dial","value":"Dark Blue"},{"label":"Weight","value":"103g"},{"label":"Bracelet","value":"Stainless Steel"},{"label":"Case","value":"Stainless Steel"}]'::jsonb,
   false, true, 8);

